Problem:
A meat processing plant has a machine that makes ham and bacon. Each kg of ham takes 15 minutes of machine time and each kg of bacon takes 8 minutes of machine time.  In a week the machine is only available for 2000 minutes. The plant can also make at most 200 kg of ham and at most 220 kg of bacon per week. If the profit per kg of ham is $20 and the profit per kg of bacon is $12, how many of each should the plant make to maximize profit?

Model and facts:
{
 "model": {
  "variables": [
   {
    "name": "kg of ham produced per week",
    "lower": 0.0,
    "upper": null,
    "integer": false
   },
   {
    "name": "kg of bacon produced per week",
    "lower": 0.0,
    "upper": null,
    "integer": false
   }
  ],
  "objective": {
   "sense": "max",
   "terms": [
    {
     "var": "kg of ham produced per week",
     "coef": 20.0
    },
    {
     "var": "kg of bacon produced per week",
     "coef": 12.0
    }
   ]
  },
  "constraints": [
   {
    "name": "machine time",
    "terms": [
     {
      "var": "kg of ham produced per week",
      "coef": 15.0
     },
     {
      "var": "kg of bacon produced per week",
      "coef": 8.0
     }
    ],
    "sense": "<=",
    "rhs": 2000.0
   },
   {
    "name": "ham capacity",
    "terms": [
     {
      "var": "kg of ham produced per week",
      "coef": 1.0
     }
    ],
    "sense": "<=",
    "rhs": 200.0
   },
   {
    "name": "bacon capacity",
    "terms": [
     {
      "var": "kg of bacon produced per week",
      "coef": 1.0
     }
    ],
    "sense": "<=",
    "rhs": 220.0
   }
  ]
 },
 "facts": {
  "objective": 2960.0,
  "values": {
   "kg of ham produced per week": 16.0,
   "kg of bacon produced per week": 220.0
  },
  "binding": [
   "machine time",
   "bacon capacity"
  ],
  "slack": {
